function readLocal<T>(key:string,fallback:T):T{try{const raw=localStorage.getItem(key);return raw?JSON.parse(raw) as T:fallback}catch{return fallback}}
function Card({c,saved,onSave,onOpen,onCreator}:{c:Character;saved:boolean;onSave:()=>void;onOpen:()=>void;onCreator?:()=>void}){return <article className="character-card"><button className="card-image-button" onClick={onOpen}><img src={c.image} alt={c.name}/><span className="card-shade"/><span className="card-badge"><Sparkles size={12}/> CHARACTER</span>{c.isPublic===false&&<span className="card-visibility">Private</span>}<span className="meet">Chat now <ArrowRight size={14}/></span></button><div className="card-body"><div className="card-title-row"><div><h3>{c.name}</h3><span className="role">{c.role}</span></div><button className={saved?"heart saved":"heart"} onClick={onSave} aria-label="Save character"><Heart size={17} fill={saved?"currentColor":"none"}/></button></div><p>{c.desc}</p><div className="card-meta">{typeof c.chatCount==="number"&&c.chatCount>0&&<span><MessageCircle size={12}/>{c.chatCount.toLocaleString()} chats</span>}{typeof c.likeCount==="number"&&c.likeCount>0&&<span><Heart size={12}/>{c.likeCount.toLocaleString()} likes</span>}{c.createdAt&&<span>{new Date(c.createdAt).toLocaleDateString(undefined,{month:"short",day:"numeric"})}</span>}</div>{c.greeting&&<p className="card-greeting">“{c.greeting}”</p>}<div className="card-bottom"><div className="card-bottom-info"><div className="tags">{c.tags.map(t=><span key={t}>{t}</span>)}</div>{c.creator&&<button type="button" className="card-creator creator-link" onClick={onCreator} disabled={!c.creatorId||!onCreator}>by {c.creator}</button>}</div><button className="card-arrow" onClick={onOpen} aria-label={"Chat with "+c.name}><MessageCircle size={16}/></button></div></div></article>}
