function saveAuthIntent(action:string,character?:Character,payload?:string){const intent={action,characterId:character?String(character.id):undefined,returnTo:character?"/characters/"+encodeURIComponent(String(character.id)):"/discover",payload};try{sessionStorage.setItem("mycharacter:auth-intent",JSON.stringify(intent));}catch{}setAuthMode("signup");setAuthError("");setAuthNotice("");setAuthOpen(true);}
function requireAuth(action:string,character?:Character,payload?:string){if(session)return false;saveAuthIntent(action,character,payload);return true;}
async function handleAuth(e:React.FormEvent){e.preventDefault();setAuthError("");setAuthNotice("");setAuthBusy(true);try{if(authMode==="signin"){const next=await signIn(authEmail,authPassword);setSession(next);setAuthOpen(false);setAuthPassword("");}else{const result=await signUp(authEmail,authPassword);if(result.session){setSession(result.session);setAuthOpen(false);setAuthPassword("");}else{setAuthNotice("Check your email to confirm your account, then sign in.");}}}catch(err){setAuthError(err instanceof Error?err.message:"Authentication failed.");}finally{setAuthBusy(false)}}
async function handleSignOut(){await signOut();setSession(null)}
const filtered=useMemo(()=>{const found=chars.filter(c=>(selectedCategories.length===0||selectedCategories.every(selected=>c.tags.some(tag=>categoryId(tag)===categoryId(selected))))&&(c.name+" "+c.role+" "+c.desc+" "+c.greeting+" "+(c.personality||"")+" "+(c.scenario||"")+" "+c.tags.join(" ")+" "+(c.creator||"")).toLowerCase().includes(query.toLowerCase()));if(discovery==="Trending")return [...found].sort((a,b)=>(b.likeCount||0)+(b.chatCount||0)*2-((a.likeCount||0)+(a.chatCount||0)*2));if(discovery==="Recommended"){const score=(c:Character)=>{const age=c.createdAt?Math.max(0,(Date.now()-Date.parse(c.createdAt))/86400000):365;const quality=[c.desc,c.greeting,c.personality,c.scenario,c.backstory].filter(value=>Boolean(value?.trim())).length*.35+Math.min(c.tags.length,5)*.15;return Math.log1p(c.chatCount||0)*2+Math.log1p(c.likeCount||0)*1.5+quality+Math.exp(-age/60)*2;};return [...found].sort((a,b)=>score(b)-score(a));}if(discovery==="Most chatted")return [...found].sort((a,b)=>(b.chatCount||0)-(a.chatCount||0));if(discovery==="New")return [...found].sort((a,b)=>Date.parse(b.createdAt||"")-Date.parse(a.createdAt||""));if(discovery==="Recently viewed")return [...found].sort((a,b)=>chats.indexOf(b.id)-chats.indexOf(a.id));return found;},[chars,selectedCategories,query,discovery,chats]);
