async function startChat(c:Character){window.history.pushState({},"","/character/"+encodeURIComponent(String(c.id)));if(!session){setActive(c);setView("Chat");setMessages(readLocal<Message[]>(accountStorageKey("history:"+c.id,null),[{from:"bot",text:c.greeting}]));setDraft("");setChatError("");setGuestPreviewCount(0);setCommunityError("");setChats(old=>[c.id,...old.filter(id=>String(id)!==String(c.id))]);return;}await open(c);}
async function open(c:Character){
window.history.pushState({},"","/character/"+encodeURIComponent(String(c.id)));
if(!session){setActive(c);setView("Chat");setMessages(readLocal<Message[]>(accountStorageKey("history:"+c.id,null),[{from:"bot",text:c.greeting}]));setChats(old=>[c.id,...old.filter(id=>String(id)!==String(c.id))]);return;}
const requestId=++chatLoadIdRef.current;
const accountId=session?.user.id??null;
const isCurrent=()=>chatLoadIdRef.current===requestId&&sessionUserIdRef.current===accountId;
setActive(c);setCommunityError("");setLiked(false);setFollowing(false);setComments([]);setMemoryItems([]);
const nextComments=typeof c.id==="string"?await listCharacterComments(c.id).catch(()=>[]):[];
if(!isCurrent())return;
setComments(nextComments);
const nextMemories=session&&typeof c.id==="string"?await listCharacterMemories(session,c.id).catch(()=>[]):[];
if(!isCurrent())return;
setMemoryItems(nextMemories);
setChats(old=>old.includes(c.id)?old:[c.id,...old]);setView("Chat");
if(session&&typeof c.id==="string"){
try{
const chatId=await getOrCreateChat(session,c.id,c.name);
if(!isCurrent())return;
const remote=await loadChatMessages(session,chatId);
if(!isCurrent())return;
if(remote.length){setMessages(remote.map(m=>({from:m.sender==="character"?"bot":"user",text:m.content})));return;}
}catch{if(!isCurrent())return;}
}
if(!isCurrent())return;
setMessages(session?[{from:"bot",text:c.greeting}]:readLocal<Message[]>(accountStorageKey("history:"+c.id,session),[{from:"bot",text:c.greeting}]));
}
async function send(text=draft){
if(!text.trim()||!active||sending)return;
if(!session&&guestPreviewCount>=10){const payload=JSON.stringify(messages);try{sessionStorage.setItem("mycharacter:auth-intent",JSON.stringify({action:"continue_preview",characterId:String(active.id),returnTo:"/character/"+encodeURIComponent(String(active.id)),payload}));}catch{}setAuthMode("signup");setAuthError("");setAuthNotice("Create a free account to continue this conversation. Your preview will be saved.");setAuthOpen(true);return;}
const userText=text.trim();const prior=messages;const pending:Message[]=[...prior,{from:"user",text:userText}];
setMessages([...pending,{from:"bot",text:""}]);setDraft("");setChatError("");setSending(true);
let chatId:string|undefined;
try{
if(session&&typeof active.id==="string"){chatId=await getOrCreateChat(session,active.id,active.name);await saveChatMessage(session,chatId,{sender:"user",content:userText});}
const response=await fetch("/api/chat",{method:"POST",headers:{"Content-Type":"application/json"},body:JSON.stringify({character:{name:active.name,role:active.role,desc:active.desc,personality:active.personality||"",scenario:active.scenario||"",backstory:active.backstory||"",greeting:active.greeting,tags:active.tags},messages:pending.slice(-20).map(m=>({role:m.from==="bot"?"assistant":"user",content:m.text}))})});
if(!response.ok){const data=await response.json().catch(()=>({}));throw new Error(data?.error||"Could not get an AI reply.");}
if(!response.body)throw new Error("Streaming is not supported by this connection.");
const reader=response.body.getReader();const decoder=new TextDecoder();let reply="";
while(true){const {value,done}=await reader.read();if(done)break;reply+=decoder.decode(value,{stream:true});setMessages([...pending,{from:"bot",text:reply}]);}
reply+=decoder.decode();if(!reply.trim())throw new Error("The AI returned an empty reply. Please try again.");
const next:Message[]=[...pending,{from:"bot",text:reply.trim()}];setMessages(next);
if(chatId&&session)await saveChatMessage(session,chatId,{sender:"character",content:reply.trim()});
if(!session){const nextCount=guestPreviewCount+1;setGuestPreviewCount(nextCount);try{localStorage.setItem(accountStorageKey("history:"+active.id,null),JSON.stringify(next));localStorage.setItem(accountStorageKey("chats",null),JSON.stringify([active.id,...readLocal<Array<number|string>>(accountStorageKey("chats",null),[]).filter(id=>String(id)!==String(active.id))]));}catch{}if(nextCount>=10){try{sessionStorage.setItem("mycharacter:auth-intent",JSON.stringify({action:"continue_preview",characterId:String(active.id),returnTo:"/character/"+encodeURIComponent(String(active.id)),payload:JSON.stringify(next)}));}catch{}setAuthMode("signup");setAuthError("");setAuthNotice("You’ve tried 10 messages for free. Create a free account to continue this conversation — your preview will be saved.");setAuthOpen(true);}}
if(session)try{localStorage.setItem(accountStorageKey("history:"+active.id,session),JSON.stringify(next));}catch{}
}catch(error){const message=error instanceof Error?error.message:"Something went wrong.";setMessages(pending);setChatError(message);if(session)try{localStorage.setItem(accountStorageKey("history:"+active.id,session),JSON.stringify(pending));}catch{}}
finally{setSending(false);}
}
