useEffect(()=>{const syncFromUrl=()=>{const path=window.location.pathname;const creatorId=path.startsWith("/creators/")?decodeURIComponent(path.slice("/creators/".length)):null;if(creatorId){const creatorChar=chars.find(c=>String(c.creatorId)===creatorId);if(creatorChar){if(view!=="Creator"||creatorProfile?.id!==creatorId)showCreator(creatorChar);return;}}const pathCharacterId=path.startsWith("/characters/")?decodeURIComponent(path.slice("/characters/".length)):path.startsWith("/character/")?decodeURIComponent(path.slice("/character/".length)):null;const characterId=pathCharacterId||new URLSearchParams(window.location.search).get("character");if(characterId){const match=chars.find(c=>String(c.id)===characterId);if(match){if(path.startsWith("/characters/")){if(view!=="Profile"||active?.id!==match.id)showProfile(match);}else if(view!=="Chat"||active?.id!==match.id)void open(match);return;}}if(path==="/chats")setView("Chats");else if(path==="/saved")setView("Saved");else if(path==="/discover"||path==="/")setView("Discover");else if(path==="/settings")setPreferencesOpen(true);};syncFromUrl();window.addEventListener("popstate",syncFromUrl);return()=>window.removeEventListener("popstate",syncFromUrl);},[chars]);
